import { parseQueryString } from '../browser';
import { Environment, EnvironmentConfigItem, IPoweredByTombolaEnvironment, IPoweredByTombolaOperator, LocaleTopLevelDomain } from '../types';

const ipRegex = /^https?:\/\/((25[0-5]|(2[0-4]|1\d|[1-9]|)\d)\.?\b){4}/;

function isUrlAnIPV4(origin: string) {
    return ipRegex.test(origin);
}

interface IPoweredByTombolaConfig {
    topLevelDomain: LocaleTopLevelDomain,
    environment: IPoweredByTombolaEnvironment,
    operator: IPoweredByTombolaOperator
}

export function getPoweredByTombolaEnvironment(fallbackTopLevelDomain: LocaleTopLevelDomain, fallbackOperator: IPoweredByTombolaOperator): IPoweredByTombolaConfig {
    const poweredByTombolaRegex = /game-([^.]+)\.(?:([^.]+)\.)?poweredbytombola\.(.+)/;
    const { origin } = window.location;

    const regexMatch = origin.match(poweredByTombolaRegex);
    if (!poweredByTombolaRegex.test(origin) || regexMatch === null) {
        if (isUrlAnIPV4(origin)) {
            return {
                environment: 'dev',
                operator: fallbackOperator,
                topLevelDomain: fallbackTopLevelDomain
            };
        }
        const environment = getPreviousEnvironment();
        switch (environment) {
            case 'live':
                return { environment: 'production', topLevelDomain: fallbackTopLevelDomain, operator: fallbackOperator };
            case 'stage':
                return { environment: 'integration', topLevelDomain: fallbackTopLevelDomain, operator: fallbackOperator };
            default:
                return { environment: 'dev', topLevelDomain: fallbackTopLevelDomain, operator: fallbackOperator };
        }
    }

    return {
        operator: regexMatch[1] as IPoweredByTombolaOperator,
        environment: (regexMatch[2] ?? 'production') as IPoweredByTombolaEnvironment,
        topLevelDomain: regexMatch[3] as LocaleTopLevelDomain
    };
}

export function getPreviousEnvironment() {
    const hostname = window.location.hostname;
    const data = parseQueryString();

    if (data && data.env !== undefined) {
        return data.env as Environment;
    }

    switch (true) {
        case (hostname.includes('dev')):
            return 'dev';
        case (hostname.includes('stage')):
            return 'stage';
        case (hostname.includes('tombola')):
            return 'live';
        default:
            return 'debug';
    }
}

export function getEnvironment(): Environment {
    const { origin } = window.location;
    if (isUrlAnIPV4(origin)) {
        return 'debug';
    }
    const environment = getPoweredByTombolaEnvironment('co.uk', 'tombola').environment;
    switch (environment) {
        case 'production':
            return 'live';
        case 'integration':
            return 'stage';
        default:
            return 'dev';
    }
}

export function isEnvironmentSetting<T>(configItem: EnvironmentConfigItem<T>): boolean {
    if (typeof configItem !== 'object') {
        return false;
    }

    return configItem.hasOwnProperty('debug') && configItem.hasOwnProperty('dev') && configItem.hasOwnProperty('stage') && configItem.hasOwnProperty('live');
}

export function getForEnvironment<T>(configItem: EnvironmentConfigItem<T>): T {
    const environment = getEnvironment();

    if (!isEnvironmentSetting<T>(configItem)) {
        throw new Error(`${JSON.stringify(configItem)} is not defined as an environment configuration item.`);
    }

    return configItem[environment];
}
